    get resourceCategories(){return ['All','Watch','Courses','Books','Ethnobotany','Identification','Nutrition','Medicine','Maps & Tools','Reference','Creators']},
    selectResourceCategory(category){this.resourceCategory=category||'All';this.$nextTick(()=>this.applyResourceFilters())},
    resourceMatches(r){const category=this.resourceCategory||'All';const q=normalize(this.resourceQuery);return (category==='All'||r.category===category)&&(!q||normalize([r.title,r.source,r.description,...r.tags].join(' ')).includes(q))},
        // Filter the pre-rendered resource cards. Static cards are intentional for kodeWeave reliability.
    applyResourceFilters(){const category=this.resourceCategory||'All';const q=normalize(this.resourceQuery||'');let visible=0;document.querySelectorAll('[data-resource-card]').forEach(card=>{const ok=(category==='All'||card.dataset.category===category)&&(!q||(card.dataset.search||'').includes(q));card.style.display=ok?'':'none';if(ok)visible++});const empty=document.querySelector('[data-resource-empty]');if(empty)empty.style.display=visible?'none':'';return visible},
    filteredResources(){return this.resources.filter(r=>this.resourceMatches(r))},
    get resourceVisibleCount(){return this.filteredResources().length},
